+function providerType(provider: RawModelsDevProvider): AiProviderType | null {
+  switch (provider.id) {
+    case "openai":
+      return "openai";
+    case "anthropic":
+      return "anthropic";
+    case "google":
+      return "google";
+    case "openrouter":
+      return "openrouter";
+    case "deepseek":
