              <button
                key={model.id}
                type="button"
                role="option"
                aria-selected={model.id === props.value}
                class="block w-full px-2 py-2 text-left hover:bg-[var(--color-paper-soft)]"
                onMouseDown$={(event) => {
                  event.preventDefault();
                  choose(model.id);
                }}
