      importBusy.value = false;
    }
  });

  const doPublish = $(async () => {
    shareBusy.value = true;
    shareError.value = null;
    shareNotice.value = null;
    try {
      if (!auth.value.user) {
        shareError.value = createAppError("AUTHENTICATION_REQUIRED", {
