      folioArtifactPath(folioId, "persona-notes.json"),
    )) ?? []
  );
}

export async function clearPersonaNotesLocally(
  folioId?: string | null,
): Promise<void> {
  if (typeof window === "undefined" || !folioId) return;
  await writeFileAsJson(folioArtifactPath(folioId, "persona-notes.json"), []);
  markDirty();
}

