      .query("rubricResults")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { folioId, result, updatedAt: now });
      return existing._id;
    }
    return await ctx.db.insert("rubricResults", {
      userId,
      folioId,
      result,
      updatedAt: now,
    });
  },
});

